/* Public interface for this SoX re-implementation.
 *
 * Original work; written from observed behaviour of the reference program.
 */
#ifndef SOX_H
#define SOX_H

#include <stdarg.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <math.h>

#if defined(_MSC_VER)
typedef __int8 int8_t;
#else
#include <stdint.h>
#endif

#ifdef __cplusplus
extern "C" {
#endif

/*--------------------------------- Basics ---------------------------------*/

typedef enum { sox_false, sox_true } sox_bool;

typedef int32_t  sox_int32_t;
typedef uint32_t sox_uint32_t;
typedef int64_t  sox_int64_t;
typedef uint64_t sox_uint64_t;

typedef int32_t sox_sample_t;

#define SOX_SAMPLE_PRECISION 32
#define SOX_SAMPLE_MAX ((sox_sample_t)2147483647L)
#define SOX_SAMPLE_MIN ((sox_sample_t)(-2147483647L - 1L))
#define SOX_SAMPLE_NEG SOX_SAMPLE_MIN
#define SOX_UNSPEC 0
#define SOX_IGNORE_LENGTH ((sox_uint64_t)(-1))
#define SOX_UNKNOWN_LEN ((sox_uint64_t)(-1))

#define SOX_SUCCESS 0
#define SOX_EOF (-1)
#define SOX_EHDR 2000
#define SOX_EFMT 2001
#define SOX_ENOMEM 2002
#define SOX_EPERM 2003
#define SOX_ENOTSUP 2004
#define SOX_EINVAL 2005

#define SOX_MAX_NLOOPS 8

/*----------------------- Sample conversion machinery -----------------------*/

extern sox_sample_t lsx_macro_temp_sample;
extern double lsx_macro_temp_double;

#define SOX_INT_MIN(bits) (1 << ((bits) - 1) == 0 ? INT_MIN : \
                           -(1 << ((bits) - 1)))
#define SOX_INT_MAX(bits) (int)(((unsigned)-1) >> (33 - (bits)))
#define SOX_UINT_MAX(bits) (int)(SOX_INT_MIN(bits) ^ SOX_INT_MAX(bits))

#define SOX_INT_TO_SAMPLE(d, bits) ((sox_sample_t)(d) << (32 - (bits)))
#define SOX_UINT_TO_SAMPLE(d, bits) \
    ((sox_sample_t)((((unsigned)(d)) ^ (unsigned)SOX_INT_MIN(bits)) << (32 - (bits))))

/* Round-to-nearest with saturation towards SOX_INT_MAX. */
#define SOX_SAMPLE_TO_SIGNED(bits, d, clips) \
    (int32_t)( \
      lsx_macro_temp_sample = (d), \
      lsx_macro_temp_sample > (sox_sample_t)(SOX_SAMPLE_MAX - (1 << (31 - (bits)))) ? \
        ++(clips), SOX_INT_MAX(bits) : \
        ((uint32_t)(lsx_macro_temp_sample + (1 << (31 - (bits))))) >> (32 - (bits)))

#define SOX_SAMPLE_TO_UNSIGNED(bits, d, clips) \
    (uint32_t)(SOX_SAMPLE_TO_SIGNED(bits, d, clips) ^ SOX_INT_MIN(bits))

#define SOX_SIGNED_8BIT_TO_SAMPLE(d, c)   SOX_INT_TO_SAMPLE(d, 8)
#define SOX_UNSIGNED_8BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 8)
#define SOX_SIGNED_16BIT_TO_SAMPLE(d, c)  SOX_INT_TO_SAMPLE(d, 16)
#define SOX_UNSIGNED_16BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 16)
#define SOX_SIGNED_24BIT_TO_SAMPLE(d, c)  SOX_INT_TO_SAMPLE(d, 24)
#define SOX_UNSIGNED_24BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 24)
#define SOX_SIGNED_32BIT_TO_SAMPLE(d, c)  ((sox_sample_t)(d))
#define SOX_UNSIGNED_32BIT_TO_SAMPLE(d, c) \
    ((sox_sample_t)((d) ^ (uint32_t)0x80000000UL))

#define SOX_SAMPLE_TO_SIGNED_8BIT(d, c)    (int8_t)SOX_SAMPLE_TO_SIGNED(8, d, c)
#define SOX_SAMPLE_TO_UNSIGNED_8BIT(d, c)  (uint8_t)SOX_SAMPLE_TO_UNSIGNED(8, d, c)
#define SOX_SAMPLE_TO_SIGNED_16BIT(d, c)   (int16_t)SOX_SAMPLE_TO_SIGNED(16, d, c)
#define SOX_SAMPLE_TO_UNSIGNED_16BIT(d, c) (uint16_t)SOX_SAMPLE_TO_UNSIGNED(16, d, c)
#define SOX_SAMPLE_TO_SIGNED_24BIT(d, c)   (int32_t)SOX_SAMPLE_TO_SIGNED(24, d, c)
#define SOX_SAMPLE_TO_UNSIGNED_24BIT(d, c) (uint32_t)SOX_SAMPLE_TO_UNSIGNED(24, d, c)
#define SOX_SAMPLE_TO_SIGNED_32BIT(d, c)   ((int32_t)(d))
#define SOX_SAMPLE_TO_UNSIGNED_32BIT(d, c) \
    (uint32_t)((d) ^ (sox_sample_t)SOX_SAMPLE_MIN)

/* Floating point <-> sample.  Full-scale is +/- 1.0 mapped onto 2^31. */
#define SOX_FLOAT_32BIT_TO_SAMPLE(d, clips) \
    (sox_sample_t)(LSX_UNUSED_VAR(lsx_macro_temp_sample), \
      lsx_macro_temp_double = (d) * (SOX_SAMPLE_MAX + 1.0), \
      lsx_macro_temp_double < SOX_SAMPLE_MIN * 1.0 ? \
        ++(clips), SOX_SAMPLE_MIN : \
      lsx_macro_temp_double >= SOX_SAMPLE_MAX + 1.0 ? \
        lsx_macro_temp_double > SOX_SAMPLE_MAX + 1.0 ? \
          ++(clips), SOX_SAMPLE_MAX : SOX_SAMPLE_MAX : \
        (sox_sample_t)lsx_macro_temp_double)
#define SOX_FLOAT_64BIT_TO_SAMPLE(d, clips) SOX_FLOAT_32BIT_TO_SAMPLE(d, clips)

#define SOX_SAMPLE_TO_FLOAT_32BIT(d, clips) \
    (float)(LSX_UNUSED_VAR(lsx_macro_temp_double), \
      lsx_macro_temp_sample = (d), \
      lsx_macro_temp_sample > SOX_SAMPLE_MAX - 64 ? \
        ++(clips), (SOX_SAMPLE_MAX - 64) * (1.0 / (SOX_SAMPLE_MAX + 1.0)) : \
        lsx_macro_temp_sample * (1.0 / (SOX_SAMPLE_MAX + 1.0)))
#define SOX_SAMPLE_TO_FLOAT_64BIT(d, clips) \
    ((double)(d) * (1.0 / (SOX_SAMPLE_MAX + 1.0)))

#define SOX_SAMPLE_CLIP_COUNT(samp, clips) do { \
    if ((samp) > SOX_SAMPLE_MAX) { (samp) = SOX_SAMPLE_MAX; ++(clips); } \
    else if ((samp) < SOX_SAMPLE_MIN) { (samp) = SOX_SAMPLE_MIN; ++(clips); } \
  } while (0)

#define SOX_ROUND_CLIP_COUNT(d, clips) \
    ((d) < 0 ? (d) <= SOX_SAMPLE_MIN - 0.5 ? ++(clips), SOX_SAMPLE_MIN \
                                           : (d) - 0.5 \
             : (d) >= SOX_SAMPLE_MAX + 0.5 ? ++(clips), SOX_SAMPLE_MAX \
                                           : (d) + 0.5)

#define SOX_INTEGER_CLIP_COUNT(type, d, clips) \
    ((d) < 0 ? (d) <= type##_MIN ? ++(clips), type##_MIN : (d) \
             : (d) >= type##_MAX ? ++(clips), type##_MAX : (d))
#define SOX_16BIT_CLIP_COUNT(d, clips) SOX_INTEGER_CLIP_COUNT(INT16, d, clips)
#define SOX_24BIT_CLIP_COUNT(d, clips) \
    ((d) < 0 ? (d) <= -8388609 ? ++(clips), -8388608 : (d) \
             : (d) >= 8388608 ? ++(clips), 8388607 : (d))

#define LSX_UNUSED_VAR(x) ((void)(x))

/*-------------------------------- Encodings --------------------------------*/

typedef enum {
  SOX_ENCODING_UNKNOWN,
  SOX_ENCODING_SIGN2,
  SOX_ENCODING_UNSIGNED,
  SOX_ENCODING_FLOAT,
  SOX_ENCODING_FLOAT_TEXT,
  SOX_ENCODING_FLAC,
  SOX_ENCODING_HCOM,
  SOX_ENCODING_WAVPACK,
  SOX_ENCODING_WAVPACKF,
  SOX_ENCODING_ULAW,
  SOX_ENCODING_ALAW,
  SOX_ENCODING_G721,
  SOX_ENCODING_G723,
  SOX_ENCODING_CL_ADPCM,
  SOX_ENCODING_CL_ADPCM16,
  SOX_ENCODING_MS_ADPCM,
  SOX_ENCODING_IMA_ADPCM,
  SOX_ENCODING_OKI_ADPCM,
  SOX_ENCODING_DPCM,
  SOX_ENCODING_DWVW,
  SOX_ENCODING_DWVWN,
  SOX_ENCODING_GSM,
  SOX_ENCODING_MP3,
  SOX_ENCODING_VORBIS,
  SOX_ENCODING_AMR_WB,
  SOX_ENCODING_AMR_NB,
  SOX_ENCODING_CVSD,
  SOX_ENCODING_LPC10,
  SOX_ENCODING_OPUS,
  SOX_ENCODINGS
} sox_encoding_t;

typedef enum {
  sox_encodings_none,      /* no bits/precision suffix */
  sox_encodings_hint_bits, /* bits shown, is a hint */
  sox_encodings_flags      /* endian etc. meaningful */
} sox_encodings_flags_t;

typedef struct {
  char const *name;
  char const *desc;
  unsigned flags;
} sox_encodings_info_t;
extern sox_encodings_info_t const sox_encodings_info[];

typedef enum {
  SOX_OPTION_NO, SOX_OPTION_YES, SOX_OPTION_DEFAULT
} sox_option_t;

typedef struct {
  double rate;
  unsigned channels;
  unsigned precision;
  sox_uint64_t length;   /* total samples (all channels) */
  double *mult;          /* volume multiplier, or NULL */
} sox_signalinfo_t;

typedef struct {
  sox_encoding_t encoding;
  unsigned bits_per_sample;
  double compression;
  sox_option_t reverse_bytes;
  sox_option_t reverse_nibbles;
  sox_option_t reverse_bits;
  sox_bool opposite_endian;
} sox_encodinginfo_t;

typedef struct {
  char const * const *names;
  unsigned int flags;
  int (*startread)(struct sox_format *ft);
  size_t (*read)(struct sox_format *ft, sox_sample_t *buf, size_t len);
  int (*stopread)(struct sox_format *ft);
  int (*startwrite)(struct sox_format *ft);
  size_t (*write)(struct sox_format *ft, sox_sample_t const *buf, size_t len);
  int (*stopwrite)(struct sox_format *ft);
  int (*seek)(struct sox_format *ft, sox_uint64_t offset);
  unsigned const *write_formats;
  double const *write_rates;
  size_t priv_size;
} sox_format_handler_t;

/* handler flags */
#define SOX_FILE_NOSTDIO  1
#define SOX_FILE_DEVICE   2
#define SOX_FILE_PHONY    4
#define SOX_FILE_REWIND   8
#define SOX_FILE_BIT_REV  16
#define SOX_FILE_NIB_REV  32
#define SOX_FILE_ENDIAN   64
#define SOX_FILE_ENDBIG   128
#define SOX_FILE_MONO     256
#define SOX_FILE_STEREO   512
#define SOX_FILE_QUAD     1024
#define SOX_FILE_CHANS (SOX_FILE_MONO | SOX_FILE_STEREO | SOX_FILE_QUAD)
#define SOX_FILE_LIT_END (SOX_FILE_ENDIAN | 0)
#define SOX_FILE_BIG_END (SOX_FILE_ENDIAN | SOX_FILE_ENDBIG)

typedef char **sox_comments_t;

typedef struct {
  unsigned char MIDInote;
  unsigned char MIDIlow;
  unsigned char MIDIhi;
  unsigned char loopmode;
  unsigned int nloops;
} sox_instrinfo_t;

typedef struct {
  sox_uint64_t start;
  sox_uint64_t length;
  unsigned int count;
  unsigned char type;
} sox_loopinfo_t;

typedef struct sox_format {
  char *filename;
  sox_signalinfo_t signal;
  sox_encodinginfo_t encoding;
  char *filetype;
  sox_comments_t oob_comments;
  sox_bool seekable;
  char mode;               /* 'r' or 'w' */
  sox_uint64_t olength;    /* samples written / declared */
  sox_uint64_t clips;
  int sox_errno;
  char sox_errstr[256];
  FILE *fp;
  int (*fclose_fn)(FILE *);
  sox_bool tell_off_valid;
  off_t tell_off;
  sox_bool eof;
  sox_format_handler_t handler;
  void *priv;
  sox_instrinfo_t instr;
  sox_loopinfo_t loops[SOX_MAX_NLOOPS];
  sox_bool instr_valid;
  /* internal bookkeeping */
  sox_uint64_t data_start;
  sox_bool ignore_length;
} *sox_format_t;

/*--------------------------------- Effects ---------------------------------*/

struct sox_effect;
typedef struct sox_effect *sox_effect_t;

typedef struct {
  char const *name;
  char const *usage;
  unsigned int flags;
  int (*getopts)(sox_effect_t effp, int argc, char *argv[]);
  int (*start)(sox_effect_t effp);
  int (*flow)(sox_effect_t effp, sox_sample_t const *ibuf,
              sox_sample_t *obuf, size_t *isamp, size_t *osamp);
  int (*drain)(sox_effect_t effp, sox_sample_t *obuf, size_t *osamp);
  int (*stop)(sox_effect_t effp);
  int (*kill)(sox_effect_t effp);
  size_t priv_size;
} sox_effect_handler_t;

#define SOX_EFF_CHAN     1   /* Effect might alter the number of channels */
#define SOX_EFF_RATE     2   /* Effect might alter sample rate */
#define SOX_EFF_PREC     4   /* Effect does its own calculation of precision */
#define SOX_EFF_LENGTH   8   /* Effect might alter audio length */
#define SOX_EFF_MCHAN    16  /* Effect handles multiple channels internally */
#define SOX_EFF_NULL     32  /* Effect does nothing */
#define SOX_EFF_DEPRECATED 64
#define SOX_EFF_GAIN     128 /* Effect does not support gain -r */
#define SOX_EFF_MODIFY   256 /* Effect does not modify samples */
#define SOX_EFF_ALPHA    512 /* Effect is experimental/incomplete */
#define SOX_EFF_INTERNAL 1024/* Effect is libSoX-only */

struct sox_effect {
  sox_effect_handler_t handler;
  sox_uint64_t clips;
  size_t flows;
  size_t flow;
  sox_signalinfo_t in_signal, out_signal;
  sox_encodinginfo_t const *in_encoding, *out_encoding;
  void *priv;
  /* internal */
  sox_sample_t *obuf;
  size_t obeg, oend;
  size_t imin;
};

typedef struct sox_effects_chain {
  sox_effect_t *effects;
  size_t length;
  size_t table_size;
  sox_effect_t *last_effects;
  sox_encodinginfo_t const *in_enc;
  sox_encodinginfo_t const *out_enc;
} sox_effects_chain_t;

sox_effect_handler_t const *sox_find_effect(char const *name);
sox_effect_t sox_create_effect(sox_effect_handler_t const *eh);
int sox_effect_options(sox_effect_t effp, int argc, char *const argv[]);
sox_effects_chain_t *sox_create_effects_chain(sox_encodinginfo_t const *in_enc,
                                              sox_encodinginfo_t const *out_enc);
void sox_delete_effects_chain(sox_effects_chain_t *ecp);
int sox_add_effect(sox_effects_chain_t *chain, sox_effect_t effp,
                   sox_signalinfo_t *in, sox_signalinfo_t const *out);
int sox_flow_effects(sox_effects_chain_t *chain,
                     int (*callback)(sox_bool all_done, void *client_data),
                     void *client_data);
size_t sox_effects_clips(sox_effects_chain_t *chain);
size_t sox_stop_effect(sox_effect_t effp);
void sox_push_effect_last(sox_effects_chain_t *chain, sox_effect_t effp);
sox_effect_t sox_pop_effect_last(sox_effects_chain_t *chain);
void sox_delete_effect(sox_effect_t effp);
void sox_delete_effects(sox_effects_chain_t *chain);

/*--------------------------------- Globals ---------------------------------*/

typedef struct {
  unsigned verbosity;
  void (*output_message_handler)(unsigned level, const char *filename,
                                 const char *fmt, va_list ap);
  sox_bool repeatable;
  size_t bufsiz;
  size_t input_bufsiz;
  sox_int32_t ranqd1;
  char const *stdin_in_use_by;
  char const *stdout_in_use_by;
  char const *subsystem;
  char *tmp_path;
  sox_bool use_magic;
  sox_bool use_threads;
  size_t log2_dft_min_size;
} sox_globals_t;
extern sox_globals_t sox_globals;

typedef struct {
  double speed;
  double *plot_data;   /* unused placeholder */
  int plot;
  sox_bool no_dither;
} sox_effects_globals_t;
extern sox_effects_globals_t sox_effects_globals;

extern char const *sox_version(void);

int sox_init(void);
int sox_quit(void);
int sox_format_init(void);
void sox_format_quit(void);

sox_format_t sox_open_read(char const *path, sox_signalinfo_t const *signal,
                           sox_encodinginfo_t const *encoding,
                           char const *filetype);
sox_format_t sox_open_write(char const *path, sox_signalinfo_t const *signal,
                           sox_encodinginfo_t const *encoding,
                           char const *filetype, sox_comments_t comments,
                           sox_bool (*overwrite_permitted)(char const *filename));
size_t sox_read(sox_format_t ft, sox_sample_t *buf, size_t len);
size_t sox_write(sox_format_t ft, sox_sample_t const *buf, size_t len);
int sox_close(sox_format_t ft);
int sox_seek(sox_format_t ft, sox_uint64_t offset, int whence);
#define SOX_SEEK_SET 0

char const *sox_strerror(int sox_errno);

/* messaging */
void sox_output_message(FILE *file, const char *filename,
                        const char *fmt, va_list ap);
void lsx_fail_impl(char const *fmt, ...);
void lsx_warn_impl(char const *fmt, ...);
void lsx_report_impl(char const *fmt, ...);
void lsx_debug_impl(char const *fmt, ...);
void lsx_debug_more_impl(char const *fmt, ...);
void lsx_debug_most_impl(char const *fmt, ...);


#ifdef __cplusplus
}
#endif
#endif

/* Internal helper interface shared by all format and effect modules. */
#ifndef SOX_I_H
#define SOX_I_H

#include "sox.h"
#include <errno.h>
#include <ctype.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif
#ifndef M_SQRT2
#define M_SQRT2 1.41421356237309504880
#endif
#ifndef M_LN10
#define M_LN10 2.30258509299404568402
#endif

#define array_length(a) (sizeof(a) / sizeof((a)[0]))
#define range_limit(x, lo, hi) ((x) < (lo) ? (lo) : (x) > (hi) ? (hi) : (x))
#define sqr(x) ((x) * (x))
#define dB_to_linear(x) exp((x) * (M_LN10 * 0.05))
#define linear_to_dB(x) (log10(x) * 20)
#ifndef min
#define min(a, b) ((a) <= (b) ? (a) : (b))
#endif
#ifndef max
#define max(a, b) ((a) >= (b) ? (a) : (b))
#endif

/* memory */
void *lsx_malloc(size_t size);
void *lsx_calloc(size_t n, size_t size);
void *lsx_realloc(void *p, size_t size);
char *lsx_strdup(char const *s);
#define lsx_free free
#define lsx_valloc(v, n) ((v) = lsx_malloc((n) * sizeof(*(v))))
#define lsx_revalloc(v, n) ((v) = lsx_realloc(v, (n) * sizeof(*(v))))
#define lsx_calloc_var(v, n) ((v) = lsx_calloc(n, sizeof(*(v))))

/* string helpers */
int lsx_strcasecmp(char const *s1, char const *s2);
int lsx_strncasecmp(char const *s1, char const *s2, size_t n);
sox_bool lsx_strends(char const *str, char const *end);
char const *lsx_find_file_extension(char const *pathname);
char *lsx_strchr(char const *s, int c);

/* option / argument parsing helpers used by effects */
enum lsx_getopt_flags { lsx_getopt_flag_none = 0, lsx_getopt_flag_opterr = 1 };
typedef struct {
  char const *const *argv;
  int argc;
  char const *shortopts;
  struct lsx_option_t const *longopts;
  int flags;
  char const *curpos;
  int ind;
  int opt;
  char const *arg;
  int lngind;
} lsx_getopt_t;
typedef struct lsx_option_t {
  char const *name;
  int has_arg;               /* 0 none, 1 required, 2 optional */
  int *flag;
  int val;
} lsx_option_t;
void lsx_getopt_init(int argc, char *const argv[], char const *shortopts,
                     lsx_option_t const *longopts, int flags,
                     int first, lsx_getopt_t *state);
int lsx_getopt(lsx_getopt_t *state);

char const *lsx_parsesamples(double rate, char const *str, uint64_t *samples,
                             int def);
char const *lsx_parseposition(double rate, char const *str, uint64_t *samples,
                              uint64_t latest, uint64_t end, int def);
int lsx_parse_frequency_k(char const *str, char **end_ptr, int key);
double lsx_parse_frequency(char const *str, char **end_ptr);
int lsx_parse_note(char const *text, char **end_ptr);
double lsx_parse_width(char const *str, char **end_ptr, int *width_type);

typedef enum {
  lsx_bw_width_Q, lsx_bw_width_bw_Hz, lsx_bw_width_bw_kHz,
  lsx_bw_width_bw_oct, lsx_bw_width_slope
} lsx_bw_width_t;

/* usage / failure reporting from effects */
int lsx_usage(sox_effect_t effp);
char *lsx_usage_lines(char **usage, char const *const *lines, size_t n);

/* File I/O helpers (endian-aware, honouring ft->encoding.reverse_bytes) */
size_t lsx_readbuf(sox_format_t ft, void *buf, size_t len);
int lsx_skipbytes(sox_format_t ft, size_t n);
int lsx_padbytes(sox_format_t ft, size_t n);
size_t lsx_writebuf(sox_format_t ft, void const *buf, size_t len);
int lsx_eof(sox_format_t ft);
int lsx_error(sox_format_t ft);
int lsx_flush(sox_format_t ft);
int lsx_seeki(sox_format_t ft, off_t offset, int whence);
off_t lsx_tell(sox_format_t ft);
void lsx_clearerr(sox_format_t ft);
void lsx_rewind(sox_format_t ft);
int lsx_unreadb(sox_format_t ft, unsigned b);
uint64_t lsx_filelength(sox_format_t ft);

int lsx_readb(sox_format_t ft, unsigned char *ub);
int lsx_writeb(sox_format_t ft, unsigned ub);
int lsx_readw(sox_format_t ft, uint16_t *uw);
int lsx_writew(sox_format_t ft, unsigned uw);
int lsx_read3(sox_format_t ft, uint32_t *u3);
int lsx_write3(sox_format_t ft, uint32_t u3);
int lsx_readdw(sox_format_t ft, uint32_t *udw);
int lsx_writedw(sox_format_t ft, uint32_t udw);
int lsx_readqw(sox_format_t ft, uint64_t *uqw);
int lsx_writeqw(sox_format_t ft, uint64_t uqw);
int lsx_readf(sox_format_t ft, float *f);
int lsx_writef(sox_format_t ft, double f);
int lsx_readdf(sox_format_t ft, double *d);
int lsx_writedf(sox_format_t ft, double d);
int lsx_readchars(sox_format_t ft, char *chars, size_t len);
int lsx_writes(sox_format_t ft, char const *c);
int lsx_reads(sox_format_t ft, char *c, size_t len);
size_t lsx_read_b_buf(sox_format_t ft, uint8_t *buf, size_t len);
